#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int r,c,k;scanf("%d %d %d",&r,&c,&k);
vector<vector<long long>>g(r,vector<long long>(c));
for(int i=0;i<r;++i)for(int j=0;j<c;++j)scanf("%lld",&g[i][j]);
priority_queue<tuple<long long,int,int>,vector<tuple<long long,int,int>>,greater<>>pq;
for(int i=0;i<min(r,k);++i)pq.push({g[i][0],i,0});
long long val=0;
for(int t=0;t<k;++t){auto [v,i,j]=pq.top();pq.pop();val=v;
if(j+1<c)pq.push({g[i][j+1],i,j+1});}
printf("%lld\n",val);return 0;}

